package inventory

import (
	"context"
	"log/slog"
	"math/rand/v2"
	"time"
)

// The upstream inventory API allows one request a minute per client (their
// rate-limit page); the interval stays at or above that with the jitter.
const (
	pollInterval = 60 * time.Second
	pollJitter   = 5 * time.Second
)

// Poller fetches the inventory and applies it, over and over.
type Poller struct {
	fetch func(context.Context) ([]Item, error)
	apply func([]Item)
	log   *slog.Logger
}

// Run polls until ctx ends. A failed fetch is logged and tried again on the
// next tick.
func (p *Poller) Run(ctx context.Context) {
	t := time.NewTimer(0)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
		}
		items, err := p.fetch(ctx)
		if err != nil {
			p.log.Warn("inventory poll failed", "err", err)
		} else {
			p.apply(items)
		}
		t.Reset(pollInterval + rand.N(pollJitter))
	}
}
